    "summary": "“지금까지 쌓아온 금융 경력, 다시 시작하기에 늦지 않았습니다.” 금융권에서 오랜 시간 고객을 만나고 금융상품을 상담해 온 경험은 쉽게 만들어지는 경력이 아닙니다. 조기 희망퇴직이나 경력단절로 잠시 금융 현장을 떠나셨더라도, 고객을 이해하고 상담해 온 경험 자체가 새로운 경쟁력이 될 수 있습니다. 삼성화재 소공HRC는 홈쇼핑 채널을 통해 연금에 가입한 고객을 관리하며, 기존 고객과의 상담 및 사후관리 업무를 중심으로 금융·보험 전문가로 성장할 수 있는 기회를 제공합니다. 새로운 영업 기반을 처음부터 만들어야 하는 부담보다, 기존 고객의 자산관리와 상담에 집중하면서 지금까지의 금융 경험을 활용할 수 있다는 것이 가장 큰 장점입니다. ■ 소공HRC에서 하는 일 ① 연금가입 고객 사후관리 연금저축보험 가입 고객을 대상으로 계좌 이전 및 계약 유지관리 등에 대한 상담을 진행합니다. ② 고객 맞춤형 금융상담 고객의 재무상황과 니즈를 파악하여 적합한 금융 포트폴리오를 상담·제안합니다. ③ 보장자산 관리 및 리밸런싱 상담 시장 상",
