    "summary": "두나미스자산운용은 멀티전략 기반의 절대수익을 추구하는 자산운용사입니다. 시장 환경의 변화 속에서도 지속 가능한 투자 기회를 발굴하고, 깊이 있는 리서치와 유연한 투자 전략을 바탕으로 차별화된 투자 성과를 만들어 가는 것을 목표로 합니다. 소수 정예의 전문 인력이 직급과 연차에 관계없이 투자 아이디어를 자유롭게 제안하고 토론하는 조직입니다. 리서치부터 집행까지 의사결정 구조가 짧고 빠르며, 한 사람 한 사람의 전문성과 판단이 운용 성과에 직접 연결되는 환경에서 일할 수 있습니다. 트레이딩본부 트레이딩팀의 Execution Trader는 PM 및 운용팀이 수립한 투자 아이디어를 시장에서 정확하고 효율적으로 체결하는 운용 프로세스의 마지막이자 가장 실전적인 접점입니다. 주식·파생상품 주문을 신속하게 집행하고 체결 품질(Best Execution)과 거래비용을 관리하며, 체결 이후 포지션·잔고의 정합성을 1차적으로 점검해 이상 징후를 조기에 포착·에스컬레이션함으로써, 운용팀이 투자 판단에만 집중할 수 있도록 지원합니다. PM",
