    "summary": "[BNK자산운용] 대체투자본부 NPL 운용역 경력직 채용 BNK자산운용에서 함께 성장할 능력있는 인재를 채용하고 있습니다. BNK자산운용은 BNK금융그룹의 계열사이며 '고객으로부터 가장 신뢰받는 자산운용사'라는 경영방침 아래, 전통적인 증권형 펀드뿐만 아니라, TDF, ETF 및 대체투자 상품까지 다양한 투자상품을 운용 중인 종합자산운용사입니다. 1. 모집부문 : 대체투자본부 NPL 운용역 경력직(차장~부장급) 2. 담당업무 - NPL 펀드 설정(블라인드 등) 및 투자 운용 3. 자격요건 및 우대사항 - NPL 투자 및 자산관리 업무 유경험자 - 부동산개발, 리츠 등 유관 업무 유경험자 우대 - 공인회계사, 감정평가사 등 관련 자격 보유자 우대 4. 채용절차 - 1차 : 서류전형 → 2차 : 실무진 면접 → 3차 : 임원 면접 5. 제출서류 및 접수처 - 제출서류 : 입사지원서(첨부 회사양식 사용, 희망직급 및 희망연봉 표기) - 접수기한 : 2026년 10월 23일(금) - 접수 및 문의처 : insa@bnkasse",
